function generateParenthesis(n: number): string[] {
  const result: string[] = [];
  const path: string[] = [];

  // open / close — сколько открывающих и закрывающих скобок уже поставлено
  const backtrack = (open: number, close: number): void => {
    // Поставили все 2n скобок — последовательность правильная по построению
    if (path.length === 2 * n) {
      result.push(path.join(''));
      return;
    }

    // Открывающую можно ставить, пока не израсходовали все n
    if (open < n) {
      path.push('(');
      backtrack(open + 1, close);
      path.pop();
    }

    // Закрывающую — только если есть незакрытая открывающая
    if (close < open) {
      path.push(')');
      backtrack(open, close + 1);
      path.pop();
    }
  };

  backtrack(0, 0);
  return result;
}

// Время: O(4^n / √n) — это n-е число Каталана, умноженное на длину строки
// Память: O(n) на рекурсию и путь (без учёта ответа)
